package main

// ❌ OLD: Using a map for a dense, bounded integer key range wastes
// memory and adds hashing cost. A map of 0..999 hashes every key,
// stores key/value pairs in buckets, and uses ~2-3x the memory of an
// equivalent slice, with slower access.
func lookup(m map[int]string, id int) string {
	return m[id] // ❌ OLD: hash + bucket scan, random seed
}

func build() map[int]string {
	m := make(map[int]string, 1000)
	for i := 0; i < 1000; i++ {
		m[i] = fmt.Sprintf("item-%d", i)
	}
	return m // ❌ OLD: inefficient for dense int keys
}

package main

// ✅ NEW: For a dense, bounded integer range, a slice is direct
// addressing: s[id] is O(1) with no hashing, no bucket scan, and
// minimal memory (just the values).
func lookup(s []string, id int) string {
	return s[id] // ✅ NEW: single bounds-checked index
}

func build() []string {
	s := make([]string, 1000) // ✅ NEW: one contiguous array
	for i := 0; i < 1000; i++ {
		s[i] = fmt.Sprintf("item-%d", i)
	}
	return s
}

// Maps remain the right choice for sparse keys, string keys, or
// dynamic key sets — the hash table pays off there.

// Also remember: map iteration order is random, and maps are not
// safe for concurrent use without a lock or sync.Map.
